"""Render the measured C frontend baseline as a self-contained interactive report."""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPORT = ROOT / 'suite/reports/c-frontend-profile-20261015.json'
ANALYSIS = ROOT / 'suite/reports/c-frontend-profile-analysis-20261015.json'
p = json.loads(REPORT.read_text())
a = json.loads(ANALYSIS.read_text())
data = {'summaries': p['summaries'], 'workloads': a['workloads'],
        'pp': {app: {k: v for k, v in row.items() if k in ['median_ms', 'round_totals_ms']} for app, row in p['preprocessing'].items()},
        'stacks': {app: {'samples': row['samples'], 'category_percent': row['category_percent']} for app, row in a['stacks'].items()}}
html = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>C frontend profile · 15 October 2026</title><style>
@layer defaults{:root{color-scheme:light dark;--foreground:light-dark(#20242b,#e5e7eb);--muted-foreground:light-dark(#606773,#9ca3af);--card:light-dark(#f4f6f8,#20242b);--border:light-dark(#dce1e7,#39414c);--font-sans:system-ui,sans-serif;--radius:12px}}*{box-sizing:border-box}body{margin:0;color:var(--foreground);font:14px/1.5 var(--font-sans);background:transparent}h2{font-size:23px;line-height:1.2;margin:0 0 8px}h3{font-size:17px;margin:24px 0 10px}p{margin:8px 0 14px}.muted,small{color:var(--muted-foreground)}.meta{font-size:12px}.lead{font-size:16px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.stat{padding:16px;background:var(--card);border-radius:var(--radius)}.stat strong{font-size:23px;display:block}.stat span{font-size:12px;color:var(--muted-foreground)}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}button,select{font:inherit;color:var(--foreground);border:1px solid var(--border);border-radius:7px;background:transparent;padding:7px 10px;cursor:pointer}button.active{background:var(--foreground);color:var(--background,light-dark(white,#17191d))}.legend{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;margin-bottom:14px}.key:before{content:'';display:inline-block;width:9px;height:9px;margin-right:5px;border-radius:2px;background:var(--c)}.chart{margin-top:10px}.chartrow{margin-bottom:18px}.rowlabel{display:flex;justify-content:space-between;margin-bottom:5px}.track{height:27px;display:flex;background:var(--card);border-radius:5px;overflow:hidden}.segment{height:27px;min-width:1px}.axis{display:flex;justify-content:space-between;color:var(--muted-foreground);font-size:11px;border-top:1px solid var(--border);padding-top:5px}.tablewrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap}th,td{text-align:right;padding:9px 8px;border-bottom:1px solid var(--border)}th:first-child,td:first-child{text-align:left;padding-left:0}th{color:var(--muted-foreground);font-weight:500}td:last-child,th:last-child{padding-right:0}.note{font-size:12px;color:var(--muted-foreground)}.finding{padding:16px;background:var(--card);border-radius:var(--radius);margin:10px 0}.finding b{display:block;margin-bottom:4px}.finding p{margin:5px 0;font-size:13px}.number{font-variant-numeric:tabular-nums}details{border-top:1px solid var(--border);padding-top:12px;margin-top:18px}summary{cursor:pointer}code{font-size:11px;overflow-wrap:anywhere}ul{padding-left:20px}li{margin:7px 0}.foot{font-size:11px;color:var(--muted-foreground);margin-top:16px}@media(max-width:450px){h2{font-size:21px}.stat{padding:16px}.stat strong{font-size:20px}.controls{gap:6px}button{font-size:12px}}
</style></head><body>
<h2>C frontend: where time goes</h2>
<p class="meta muted">Local main <code>ae7c2f8</code> · Apple M5 Max · Rust 1.99 · optimized release + symbols · 15 Oct 2026</p>
<p class="lead"><strong>Start with native preprocessing.</strong> It takes 74–96% of the estimated raw-C-to-IR cost in these three applications. Within C-to-IR, the balance shifts from lexing/parsing in Lua toward IR generation in SQLite.</p>
<div class="stats"><div class="stat"><strong>44</strong><span>real translation units</span></div><div class="stat"><strong>1.99M</strong><span>C tokens, all files</span></div><div class="stat"><strong>9 rounds</strong><span>per timing configuration</span></div></div>
<div class="controls"><button id="native" class="active" onclick="setBoundary(true)">Native C → IR</button><button id="resident" onclick="setBoundary(false)">Preprocessed C → IR</button><select id="debug" aria-label="Debug information" onchange="draw()"><option value="normal">Without debug info</option><option value="debug">With debug info</option></select></div>
<div id="legend" class="legend"></div><div id="chart" class="chart" aria-label="Frontend stage times"></div><div id="axis" class="axis"></div>
<p id="chartnote" class="note"></p>
<div class="tablewrap"><table><thead><tr><th>Application</th><th>Files</th><th>Preprocess</th><th>C → IR</th><th>Observed C → IR range</th><th>IR drop</th></tr></thead><tbody id="totals"></tbody></table></div>
<p class="note">Milliseconds per serial application batch. C → IR uses the unchanged API; range is min–max over nine rounds, not a confidence interval. IR destruction is separate.</p>
<h3>What the samples point to</h3>
<div class="finding"><b>1. Preprocessor scanning and token storage</b><p>Scanning appears in <strong>49–51%</strong> of preprocessing samples; allocator stacks appear in <strong>36–38%</strong>. Token cloning appears in <strong>12–15%</strong>. These overlap and must not be added.</p><p>First experiments: compact token text and file identities; reduce repeated token copies; cache scanned headers with correct include-guard and macro handling. <code>preprocess.rs: scan, file, expand</code></p></div>
<div class="finding"><b>2. Lexer punctuation recognition and identifier ownership</b><p>Lexing takes <strong>25–39%</strong> of C-to-IR time without debug info. <code>tokenize</code> is a leading sampled function; many comparison samples sit directly beneath it. The lexer currently searches a 48-entry punctuation list and allocates identifier strings.</p><p>Try dispatching punctuation by first byte, then measure borrowing or interning identifier text. The exact benefit of either change remains unmeasured. <code>lex.rs: Lexer::next</code></p></div>
<div class="finding"><b>3. SSA construction for large functions</b><p>SQLite spends <strong>43%</strong> of C-to-IR time in IR generation. SSA builder frames appear in <strong>27%</strong> of its compile-and-drop samples, including <strong>16%</strong> through <code>seal_block</code> and <strong>12%</strong> through <code>read</code> (overlapping).</p><p><code>find_preds</code> scans all built blocks each time a block is sealed. Maintaining predecessor edges is a concrete candidate; the scan is inlined, so the sample cannot isolate its exact share. <code>keel-frontend/src/lib.rs</code></p></div>
<h3>Representative files within each application</h3><div class="tablewrap"><table><thead><tr><th>File</th><th>Tokens</th><th>Functions</th><th>Lex</th><th>Parse/types</th><th>IR gen</th><th>Total</th></tr></thead><tbody id="files"></tbody></table></div>
<p class="note">Largest files by measured C-to-IR time; without debug info. Application totals include every file, including generated QuickJS data. Individual medians need not sum to batch medians.</p>
<details><summary>Method, validation, and limits</summary><ul><li>Lua 5.4.7: 33 files; QuickJS 2024-01-13 with BigNum: 9; SQLite 3.46.1 amalgamation + shell: 2. Native preprocessing uses the suite’s macOS defines and the local SDK.</li><li>Native preprocessing includes transitive header reads, scanning, macro expansion, text formatting and internal cleanup. Raw top-level files are resident; SDK discovery by xcrun is outside timing.</li><li>C-to-IR uses the native preprocessor’s output in memory. Parsing includes name resolution and type checking. Cleanup includes parser, token and typed-tree destruction. Optimizer, IR verifier, backend, file reading and process startup are outside these stage timings.</li><li>Each process warms both compile APIs and checks full Debug IR equality and IR verification for every input. All 44 native-preprocessed inputs also compile and verify before timing. The 17 preprocessing/environment tests pass.</li><li>Applications and compile timing modes are shuffled with a fixed seed; file order rotates across rounds. Staged/unchanged API paired median ratios are 0.995–1.004 across all six application/debug combinations. This is a measurement-overhead check, not an optimization comparison.</li><li>Seven six-second macOS stack captures sample the unchanged compile-and-drop loop (all three apps and SQLite debug) and native preprocessing (all three apps). Stack percentages are inclusive sample shares with recursive frames counted once; categories can overlap. Sampling is separate from timing.</li><li>Debug-info mode keeps named locals in memory and changes SSA construction; it can lower IR-generation time despite extra debug metadata. It is a different output mode, not a before/after optimization.</li><li>Warm caches, one host, serial library measurements. Native C → IR bars add independent preprocessing and stage medians; they estimate the combined boundary and are not measured end-to-end wall times. No optimization has been applied or speedup established.</li></ul></details>
<p class="foot">Raw measurements, input/source/binary hashes, commands, sample trees and the reproduction scripts are saved alongside this report.</p>
<script>const D=__DATA__;let native=true;const apps=['lua','quickjs','sqlite'];const labels={lua:'Lua',quickjs:'QuickJS',sqlite:'SQLite'};const keys=['preprocess_ms','lex_ms','parse_ms','irgen_ms','cleanup_ms'];const colors=['#9767d4','#4d9ed6','#46aa93','#e4a14d','#9098a6'];const names=['Preprocess','Lex','Parse / types','IR generation','Cleanup'];const fmt=n=>n.toFixed(1);function setBoundary(x){native=x;draw()}function draw(){const mode=document.getElementById('debug').value;document.getElementById('native').classList.toggle('active',native);document.getElementById('resident').classList.toggle('active',!native);const entries=apps.map(app=>{const s=D.summaries[app+':'+mode];const v=s.staged.median_ms;return{app,s,values:[native?D.pp[app].median_ms:0,v.lex_ms,v.parse_ms,v.irgen_ms,v.cleanup_ms]}});let max=Math.max(...entries.map(e=>e.values.reduce((a,b)=>a+b,0)));max=Math.ceil(max/(native?200:25))*(native?200:25);document.getElementById('legend').innerHTML=names.map((n,i)=>!native&&i===0?'':`<span class="key" style="--c:${colors[i]}">${n}</span>`).join('');document.getElementById('chart').innerHTML=entries.map(e=>{const total=e.values.reduce((a,b)=>a+b,0);return `<div class="chartrow"><div class="rowlabel"><b>${labels[e.app]}</b><span class="number">${fmt(total)} ms${native?' estimated':''}</span></div><div class="track">${e.values.map((v,i)=>v?`<div class="segment" style="width:${100*v/max}%;background:${colors[i]}" title="${names[i]}: ${fmt(v)} ms (${(100*v/total).toFixed(1)}%)"></div>`:'').join('')}</div></div>`}).join('');document.getElementById('axis').innerHTML=[0,.25,.5,.75,1].map(v=>`<span>${Math.round(v*max)} ms</span>`).join('');document.getElementById('chartnote').textContent=native?'Sum of independent stage medians; hover over segments for values. Returned IR destruction is excluded.':'Stage medians on resident preprocessed input; hover for values. Returned IR destruction is excluded.';document.getElementById('totals').innerHTML=entries.map(e=>{const b=e.s.baseline;return`<tr><td>${labels[e.app]}</td><td>${D.workloads[e.app].files}</td><td>${fmt(D.pp[e.app].median_ms)}</td><td><strong>${fmt(b.median_ms.total_ms)}</strong></td><td>${fmt(b.min_ms)}–${fmt(b.max_ms)}</td><td>${fmt(b.median_ms.module_drop_ms)}</td></tr>`}).join('');document.getElementById('files').innerHTML=apps.flatMap(app=>D.workloads[app].top_files.slice(0,2).map(f=>`<tr><td>${f.name}</td><td>${f.tokens.toLocaleString()}</td><td>${f.functions.toLocaleString()}</td><td>${fmt(f.lex_ms)}</td><td>${fmt(f.parse_ms)}</td><td>${fmt(f.irgen_ms)}</td><td><strong>${fmt(f.total_ms)}</strong></td></tr>`)).join('');}draw();console.log('rendered',apps.length,'applications; 44 files; controls ready');</script></body></html>'''
html = html.replace('__DATA__', json.dumps(data, separators=(',', ':')))
output = ROOT / 'suite/reports/c-frontend-profile-20261015.html'
output.write_text(html)
print(output)
